export const byId = (id) => EX.find(e => e.id === id);
export const cById = (id) => CARDIO.find(c => c.id === id);
export const primary = (e) => (e.m && e.m[0]) || '';

// AI helpers
export const byCategory = (cat) => EX.filter(e => e.cat === cat);
export const byEquipment = (equipment) => EX.filter(e => e.equipment === equipment || (e.eq||[]).some(eq => eq.toLowerCase().includes((equipment||'').toLowerCase())));
export const byLocation = (loc) => EX.filter(e => e.loc === loc);
export const getEquivalents = (id) => {
  const ex = byId(id);
  if (!ex) return [];
  return (ex.equivalents||[]).map(byId).filter(Boolean);
};
export const getSubstitutes = (id, opts={}) => {
  // Find ex's that target same primary muscle and respect filters
  const ex = byId(id);
  if (!ex) return [];
  const primary = (ex.muscles_primary||[])[0];
  if (!primary) return [];
  let candidates = EX.filter(e => e.id !== id && (e.muscles_primary||[]).includes(primary));
  if (opts.location) candidates = candidates.filter(e => e.loc === opts.location);
  if (opts.equipment) candidates = candidates.filter(e => e.equipment === opts.equipment);
  if (opts.maxDifficulty != null) candidates = candidates.filter(e => (e.technical_difficulty||3) <= opts.maxDifficulty);
  return candidates;
};
export const getProgressions = (id) => (byId(id)?.progressions||[]).map(byId).filter(Boolean);
export const getRegressions = (id) => (byId(id)?.regressions||[]).map(byId).filter(Boolean);
